**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int ile = 0;
    while (plik >> liczba) {
        int kopia = liczba;
        int iloczyn = 1;
        while (kopia > 0) {
            iloczyn *= kopia % 10;
            kopia /= 10;
        }
        cout << liczba << ": iloczyn cyfr = " << iloczyn;
        if (iloczyn % 2 == 0) {
            cout << " -> TAK" << endl;
            ile++;
        } else {
            cout << " -> NIE" << endl;
        }
    }
    cout << "Liczb z parzystym iloczynem cyfr: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Iloczyn cyfr obliczamy w petli while, wyodrebniajac kolejne cyfry przez `% 10` i `/= 10`. Iloczyn jest parzysty, jesli co najmniej jedna cyfra jest parzysta (wlacznie z 0). Akumulator inicjujemy na 1.

